import{_ as l,a0 as d,w as u,s as a,I as n,x as t,a1 as o,A as e,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"遷移到 Linux：使用 sudo | LCTT x X-CMD","titleTemplate":false,"description":"遷移到 Linux：使用 sudo | LCTT (201807) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"遷移到 Linux：使用 sudo | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"遷移到 Linux：使用 sudo | LCTT (201807) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201807/20180313 Migrating to Linux- Using Sudo","title":"遷移到 Linux：使用 sudo","tag":"201807","desc":""},"relativePath":"201807/20180313 Migrating to Linux- Using Sudo.md","filePath":"[post].md"}'),p={name:"201807/20180313 Migrating to Linux- Using Sudo.md"};function g(x,s,f,m,h,b){const i=d("Link");return u(),a("div",null,[s[22]||(s[22]=n("h1",{id:"遷移到-linux-使用-sudo",tabindex:"-1"},[t("遷移到 Linux：使用 sudo "),n("a",{class:"header-anchor",href:"#遷移到-linux-使用-sudo","aria-label":"Permalink to “遷移到 Linux：使用 sudo”"},"​")],-1)),s[23]||(s[23]=n("blockquote",null,[n("p",null,"sudo 機制可以讓你輕鬆以普通用户偶爾執行管理任務。讓我們來學習一下。")],-1)),s[24]||(s[24]=n("p",null,[n("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/ray-hennessy-233438-unsplash.jpg?itok=d4l7QUtF",alt:""})],-1)),s[25]||(s[25]=n("p",null,"本文是我們關於遷移到 Linux 的系列文章的第五篇。如果你錯過了之前的那些，你可以在這裏趕上：",-1)),n("p",null,[o(i,{href:"https://linux.cn/article-9212-1.html"},{default:e(()=>[...s[0]||(s[0]=[t("第1部分 - 入門介紹",-1)])]),_:1}),o(i,{href:"https://linux.cn/article-9213-1.html"},{default:e(()=>[...s[1]||(s[1]=[t("第2部分 - 磁盤、文件和文件系統",-1)])]),_:1}),o(i,{href:"https://linux.cn/article-9293-1.html"},{default:e(()=>[...s[2]||(s[2]=[t("第3部分 - 圖形操作環境",-1)])]),_:1}),o(i,{href:"https://linux.cn/article-9565-1.html"},{default:e(()=>[...s[3]||(s[3]=[t("第4部分 - 命令列",-1)])]),_:1})]),s[26]||(s[26]=r(`<p>你可能一直想了解 Linux。也許它在你的工作場所使用，如果你每天使用它，你的工作效率會更高。或者，也許你想在家裏的某些計算機上安裝 Linux。無論是什麼原因，這一系列文章都是為了讓過渡更容易。</p><p>與許多其他操作系統一樣，Linux 支持多用户。它甚至支持多個用户同時登錄。</p><p>用户帳户通常會被分配一個可以存儲文件的家目錄。通常這個家目​​錄位於：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/home/&lt;login name&gt;</span></span></code></pre></div><p>這樣，每個用户都有存儲自己的文檔和其他文件的獨立位置。</p><h3 id="管理任務" tabindex="-1">管理任務 <a class="header-anchor" href="#管理任務" aria-label="Permalink to “管理任務”">​</a></h3><p>在傳統的 Linux 安裝中，常規用户帳户無權在系統上執行管理任務。典型的安裝 Linux 的系統會要求用户以管理員身份登錄以執行某些任務，而不是為每個用户分配權限以執行各種任務。</p><p>Linux 上的管理員帳户稱為 root。</p><h3 id="sudo-解釋" tabindex="-1">Sudo 解釋 <a class="header-anchor" href="#sudo-解釋" aria-label="Permalink to “Sudo 解釋”">​</a></h3><p>從歷史上看，要執行管理任務，必須以 root 身份登錄，執行任務，然後登出。這個過程有點乏味，所以很多人以 root 登錄並且整天都以管理員身份工作。這種做法可能會導致災難性的後果，例如，意外刪除系統中的所有文件。當然，root 用户可以做任何事情，因此沒有任何保護措施可以防止有人意外地執行影響很大的操作。</p><p>創建 <code>sudo</code> 工具是為了使你更容易以常規用户帳户登錄，偶爾以 root 身份執行管理任務，而無需登錄、執行任務然後登出。具體來説，<code>sudo</code> 允許你以不同的用户身份運行命令。如果你未指定特定用户，則假定你指的是 root 用户。</p><p><code>sudo</code> 可以有複雜的設置，允許用户有權限使用 <code>sudo</code> 運行某些命令，而其他的不行。通常，安裝的桌面系統會使創建的第一個帳户在 <code>sudo</code> 中有完全的權限，因此你作為主要用户可以完全管理 Linux 安裝。</p><h3 id="使用-sudo" tabindex="-1">使用 Sudo <a class="header-anchor" href="#使用-sudo" aria-label="Permalink to “使用 Sudo”">​</a></h3><p>某些安裝 Linux 的系統設置了 <code>sudo</code>，因此你仍需要知道 root 帳户的密碼才能執行管理任務。其他人，設置 <code>sudo</code> 輸入自己的密碼。這裏有不同的哲學。</p><p>當你嘗試在圖形環境中執行管理任務時，通常會打開一個要求輸入密碼的對話框。輸入你自己的密碼（例如，在 Ubuntu 上）或 root 帳户的密碼（例如，Red Hat）。</p><p>當你嘗試在命令列中執行管理任務時，它通常只會給你一個 “permission denied” 錯誤。然後你在前面用 <code>sudo</code> 重新運行命令。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl start vsftpd</span></span>
<span class="line"><span>Failed to start vsftpd.service: Access denied</span></span>
<span class="line"><span></span></span>
<span class="line"><span>sudo systemctl start vsftpd</span></span>
<span class="line"><span>[sudo] password for user1:</span></span></code></pre></div><h3 id="何時使用-sudo" tabindex="-1">何時使用 Sudo <a class="header-anchor" href="#何時使用-sudo" aria-label="Permalink to “何時使用 Sudo”">​</a></h3><p>以 root 身份運行命令（在 <code>sudo</code> 或其他情況下）並不總是解決權限錯誤的最佳解決方案。雖然將以 root 身份運行會消除 “permission denied” 錯誤，但有時最好尋找根本原因而不是僅僅解決症狀。有時文件擁有錯誤的所有者和權限。</p><p>當你在嘗試一個需要 root 權限來執行操作的任務或者程序時使用 <code>sudo</code>。如果文件恰好由另一個用户（包括 root 用户）擁有，請不要使用 <code>sudo</code>。在第二種情況下，最好正確設置文件的權限。</p>`,20)),n("p",null,[s[5]||(s[5]=t("通過 Linux 基金會和 edX 的免費",-1)),o(i,{href:"https://training.linuxfoundation.org/linux-courses/system-administration-training/introduction-to-linux"},{default:e(()=>[...s[4]||(s[4]=[t("“Linux 介紹”",-1)])]),_:1}),s[6]||(s[6]=t("課程瞭解有關 Linux 的更多信息。",-1))]),s[27]||(s[27]=n("hr",null,null,-1)),n("p",null,[s[8]||(s[8]=t("via: ",-1)),o(i,{href:"https://www.linux.com/blog/learn/2018/3/migrating-linux-using-sudo"},{default:e(()=>[...s[7]||(s[7]=[t("https://www.linux.com/blog/learn/2018/3/migrating-linux-using-sudo",-1)])]),_:1})]),n("p",null,[s[13]||(s[13]=t("作者：",-1)),o(i,{href:"https://www.linux.com/users/johnbonesio"},{default:e(()=>[...s[9]||(s[9]=[t("John Bonesio",-1)])]),_:1}),s[14]||(s[14]=t(" 選題：",-1)),o(i,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[10]||(s[10]=[t("lujun9972",-1)])]),_:1}),s[15]||(s[15]=t(" 譯者：",-1)),o(i,{href:"https://github.com/geekpi"},{default:e(()=>[...s[11]||(s[11]=[t("geekpi",-1)])]),_:1}),s[16]||(s[16]=t(" 校對：",-1)),o(i,{href:"https://github.com/wxy"},{default:e(()=>[...s[12]||(s[12]=[t("wxy",-1)])]),_:1})]),n("p",null,[s[19]||(s[19]=t("本文由 ",-1)),o(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[17]||(s[17]=[t("LCTT",-1)])]),_:1}),s[20]||(s[20]=t(" 原創編譯，",-1)),o(i,{href:"https://linux.cn/"},{default:e(()=>[...s[18]||(s[18]=[t("Linux中國",-1)])]),_:1}),s[21]||(s[21]=t(" 榮譽推出",-1))])])}const C=l(p,[["render",g]]);export{T as __pageData,C as default};
